import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"4.4 控制打扰与验收主动服务","description":"主动模式要安静、有用、可控，并且可以随时关掉。","frontmatter":{"title":"4.4 控制打扰与验收主动服务","description":"主动模式要安静、有用、可控，并且可以随时关掉。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/4-4.md","filePath":"delivery/stage-4/4-4.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-4/4-4.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_4-4-控制打扰与验收主动服务" tabindex="-1">4.4 控制打扰与验收主动服务 <a class="header-anchor" href="#_4-4-控制打扰与验收主动服务" aria-label="Permalink to &quot;4.4 控制打扰与验收主动服务&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让主动模式安静、有用、可控，并通过真实任务证明它没有变成通知噪音。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>设置每日打断上限、安静时段和同类事件聚合规则。</li><li>提供随时暂停、降级和关闭主动模式的入口，并说明当前处于哪种模式。</li><li>记录每条主动建议是否被接受、忽略或转成任务，以及用户是否觉得有用。</li><li>用 5–10 个真实主动任务检验：平均每个任务打断不超过一次，用户能理解为什么被提醒。</li><li>高风险动作仍然需要审批，手机审批不能被重复使用。</li><li>如果用户开始关闭通知、忽略审批或觉得被打扰，先降低主动性，而不是继续增加功能。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
